import { pt, enUS, es } from 'date-fns/locale';

export type MessageMap = {
  [key: string]: { [key: string]: string | MessageMap } | string;
};

const DEFAULT_LANGUAGE = 'en';

export const getTranslationsDate = (language = DEFAULT_LANGUAGE): Locale => {
  const translations: { [index: string]: Locale } = {
    en: enUS,
    pt,
    es,
  };

  return translations[language];
};

export const getTranslateLabel = (id: string, language = DEFAULT_LANGUAGE): string => {
  const translations: any = {
    en: {
      to: 'to',
      formatDate: 'MMM dd, yyyy',
    },
    pt: {
      to: 'a',
      formatDate: 'dd MMM, yyyy',
    },
    es: {
      to: 'al',
      formatDate: 'dd MMM, yyyy',
    },
  };

  return translations[language][id] || id;
};
